function createLessonCardSecure(lesson, completed) {
 let status = getStatus(lesson.id, completed);
 let isLocked = status === 'locked';

 let card = mockDOM.createElement('article');
 card.className = `lesson-card ${isLocked? 'locked' : ''}`;
 card.setAttribute = (n, v) => {}; // Accessibility - aria-label etc.

 // Secure: Use textContent for user data to prevent XSS
 // For demo, innerHTML with trusted template but data via textContent in real secure version
