 let badgeText = status === 'completed'? 'Completed' : status === 'current'? 'Current' : 'Locked';

 // In secure version, you'd do:
 // const h3 = document.createElement('h3'); h3.textContent = lesson.title; card.appendChild(h3);
 // For brevity, using innerHTML with trusted static data safe, but note security
 card.innerHTML = `
 <div class="lesson-number">
 <span class="lesson-badge">Lesson ${lesson.id}</span>
 <span class="status ${status}">${badgeText}</span>
 </div>
 <h3>${lesson.title}</h3>
