 <button class="start-btn" data-lesson="${lesson.id}" ${isLocked? 'disabled aria-label="Lesson locked"' : `aria-label="Start lesson ${lesson.id}"`}>${isLocked? 'Locked' : status === 'completed'? 'Review' : 'Start Lesson'}</button>
 `;

