function updateProgress(completed) {
 let progressFill = mockDOM.getElementById('progressFill');
 let progressText = mockDOM.getElementById('progressText');
 let lessonCount = mockDOM.getElementById('lessonCount');
 if (!progressFill ||!progressText ||!lessonCount) return;

 completed = Math.min(TOTAL_LESSONS, Math.max(0, Number(completed) || 0));
 let percent = Math.round((completed / TOTAL_LESSONS) * 100);

 progressFill.style.width = `${percent}%`; // Style
